// closing_date = H-1 WIB, format YYYYMMDD -- SATU titik tanggal
// (bukan rentang), pola PERSIS 'timeRange' workflow lama 'Get sales
// & biaya online'. Workflow dijalankan 05:50 WIB supaya settlement
// platform untuk closing_date H-1 sudah final saat ditarik.
const now = new Date();
const wibNow = new Date(now.getTime() + 7 * 3600 * 1000);
const yesterday = new Date(wibNow.getTime() - 24 * 3600 * 1000);
const yyyy = yesterday.getUTCFullYear();
const mm = String(yesterday.getUTCMonth() + 1).padStart(2, '0');
const dd = String(yesterday.getUTCDate()).padStart(2, '0');
return [{ json: { closing_date: `${yyyy}${mm}${dd}` } }];

const row = $input.item.json;
if (!row) throw new Error('Token Shopee tidak ditemukan di api_tokens untuk platform shopeefood');
if (row.status !== 'valid') throw new Error(`Token Shopee status: ${row.status} -- cek dan refresh manual dulu di api_tokens`);
if (row.expires_at && new Date(row.expires_at) < new Date()) throw new Error(`Token Shopee sudah expired pada ${row.expires_at} -- refresh manual dulu`);

let tokenHeaders;
try { tokenHeaders = typeof row.token === 'string' ? JSON.parse(row.token) : row.token; }
catch (e) { throw new Error('Kolom token Shopee bukan JSON valid'); }

const headers = {
  ...tokenHeaders,
  priority: 'u=1, i',
  'sec-ch-ua': '"Google Chrome";v="149", "Chromium";v="149", "Not)A;Brand";v="24"',
  'sec-ch-ua-mobile': '?0',
  'sec-ch-ua-platform': '"macOS"',
  'sec-fetch-dest': 'empty',
  'sec-fetch-mode': 'cors',
  'sec-fetch-site': 'same-site',
};

const closing_date = $('Tentukan Closing Date').first().json.closing_date;
return [{ json: { headers, closing_date } }];

// Paginasi SUDAH ADA di workflow lama (while-loop, page_size=10) --
// dipakai ulang apa adanya, sudah aman.
const ctx = $('Validasi Token Shopee').first().json;
const { headers, closing_date } = ctx;
const mw = '20809370';

let allLogs = [];
let page_num = 1;
const page_size = 10;

while (true) {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://foody.shopee.co.id/api/seller/v1/wallet/transaction/search/details',
    headers,
    body: { filter: { settlement_id: '', closing_date }, summary_type: 2, page_num, page_size, mw },
    json: true,
    ignoreHttpStatusErrors: true,
  });

  if (response.code !== 0) {
    if (page_num > 1) break;
    throw new Error(`Shopee API error (code ${response.code}): ${response.msg} | closing_date=${closing_date} page_num=${page_num}`);
  }

  const logs = (response && response.data && response.data.transaction_logs) || [];
  allLogs = allLogs.concat(logs);

  if (logs.length < page_size) break;
  page_num++;
}

return allLogs.map(log => ({ json: { ...log, closing_date, headers, mw } }));

const log = $input.item.json;
const response = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://foody.shopee.co.id/api/seller/v1/wallet/transaction/clearing-detail/${log.id}?mw=${log.mw}`,
  headers: log.headers,
  json: true,
  ignoreHttpStatusErrors: true,
});

if (response.code !== 0) throw new Error(`Shopee clearing-detail error (code ${response.code}): ${response.msg} | id=${log.id}`);

await new Promise(resolve => setTimeout(resolve, 400));

return { json: { ...log, clearing: (response && response.data && response.data.clearing) || {} } };

// -> 13 kolom KOLOM_TRANSAKSI.
const d = $input.item.json;
const c = d.clearing || {};
const amt = c.amount || {};

function toIDR(v) { return v ? Number(v) / 100000 : 0; }
function toWIBString(ms) {
  if (!ms || ms === '0') return null;
  const date = new Date(Number(ms));
  const wib = new Date(date.getTime() + 7 * 3600 * 1000);
  const yyyy = wib.getUTCFullYear();
  const mm = String(wib.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(wib.getUTCDate()).padStart(2, '0');
  const hh = String(wib.getUTCHours()).padStart(2, '0');
  const mi = String(wib.getUTCMinutes()).padStart(2, '0');
  const ss = String(wib.getUTCSeconds()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}T${hh}:${mi}:${ss}+07:00`;
}

const statusMap = { 1: 'Pending', 2: 'Selesai', 3: 'Dibatalkan' };

return { json: {
  platform: 'shopeefood',
  platform_order_number: c.reference_id || '',
  platform_transaction_id: c.id || d.id,
  order_time: toWIBString(c.create_time),
  settled_time: toWIBString(c.complete_time),
  status: statusMap[c.settlement_status] || `unknown_${c.settlement_status}`,
  gross_amount: toIDR(amt.item_subtotal),
  total_fees: toIDR(amt.store_subsidy) + toIDR(amt.commission),
  net_revenue: toIDR(amt.amount),
  currency: 'IDR',
  source: 'api_clearing_detail',
  source_id: c.id || d.id,
  raw_payload: JSON.stringify(c),
} };

