// Paginasi SUDAH ADA di workflow lama (while-loop offset/limit=50)
// -- dipakai ulang apa adanya, sudah aman.
const ctx = $('Validasi Token GrabFood').first().json;
const { headers, closing_date, store_id, merchant_group_id } = ctx;

function randomRequestId() {
  const chars = 'abcdef0123456789';
  let s = '';
  for (let i = 0; i < 32; i++) s += chars[Math.floor(Math.random() * chars.length)];
  return s;
}
function nowWIBISO() {
  const now = new Date();
  const wib = new Date(now.getTime() + 7 * 3600 * 1000);
  const yyyy = wib.getUTCFullYear();
  const mm = String(wib.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(wib.getUTCDate()).padStart(2, '0');
  const hh = String(wib.getUTCHours()).padStart(2, '0');
  const mi = String(wib.getUTCMinutes()).padStart(2, '0');
  const ss = String(wib.getUTCSeconds()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}T${hh}:${mi}:${ss}+07:00`;
}
function toDDMMYY(yyyy_mm_dd) {
  const [y, m, d] = yyyy_mm_dd.split('-');
  return `${d}/${m}/${y.slice(2)}`;
}

let allTx = [];
let offset = 0;
const limit = 50;

while (true) {
  const url = `https://merchant.grab.com/mex/finances/v1/store/${store_id}/transactions?merchant_group_id=${merchant_group_id}&from=${closing_date}&to=${closing_date}&limit=${limit}&offset=${offset}&multi_entity_ids=&currency=IDR`;

  const response = await this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: {
      ...headers,
      referer: `https://merchant.grab.com/finances?page=st&startDate=${toDDMMYY(closing_date)}&endDate=${toDDMMYY(closing_date)}&grabID=${store_id}`,
      'x-date': nowWIBISO(),
      'x-request-id': randomRequestId(),
    },
    json: true,
    ignoreHttpStatusErrors: true,
  });

  if (response.error) {
    if (offset > 0) break;
    throw new Error(`GrabFood API error: ${JSON.stringify(response.error)} | closing_date=${closing_date} offset=${offset}`);
  }

  const rows = response.data || [];
  allTx = allTx.concat(rows);

  if (rows.length < limit) break;
  offset += limit;
}

return allTx.map(tx => ({ json: { ...tx, closing_date } }));

