const auth = $('Validasi Token GoFood').first().json;
const { authorization, merchant_id, user_agent, closing_date_raw } = auth;

function toWIBDayRangeUTC(yyyymmdd) {
  const y = yyyymmdd.slice(0, 4), m = yyyymmdd.slice(4, 6), d = yyyymmdd.slice(6, 8);
  const startWIB = new Date(`${y}-${m}-${d}T00:00:00+07:00`);
  const endWIB = new Date(`${y}-${m}-${d}T23:59:59.999+07:00`);
  return { start_time: startWIB.toISOString(), end_time: endWIB.toISOString() };
}

const { start_time, end_time } = toWIBDayRangeUTC(closing_date_raw);
const headers = {
  accept: 'application/json, text/plain, */*',
  'accept-language': 'en-US,en;q=0.9,id;q=0.8',
  'authentication-type': 'go-id',
  authorization,
  'content-type': 'application/json',
  origin: 'https://portal.gofoodmerchant.co.id',
  referer: 'https://portal.gofoodmerchant.co.id/',
  'user-agent': user_agent,
};

let allTx = [];
let from = 0;
