while (true) {
  const url = `https://api.gojekapi.com/merchant-analytics/v2/merchants/transactions?from=${from}&size=${size}&statuses=SETTLEMENT,CAPTURE,REFUND,PARTIAL_REFUND&payment_types=QRIS,GOPAY,OFFLINE_CREDIT_CARD,OFFLINE_DEBIT_CARD,CREDIT_CARD&start_time=${start_time}&end_time=${end_time}&merchant_ids=${merchant_id}`;

  const response = await this.helpers.httpRequest({ method: 'GET', url, headers, json: true, ignoreHttpStatusErrors: true });

  const rows = Array.isArray(response) ? response : ((response && (response.data || response.transactions)) || []);
  allTx = allTx.concat(rows);

  if (rows.length < size) break;
  from += size;
}

return allTx.map(tx => ({ json: tx }));

