return payouts.filter(p => p.status === 'paid').map(p => ({ json: { payout_id: p.payout_id } }));

const auth = $('Validasi Token GoFood').first().json;
const { authorization, user_agent } = auth;

let allAdjustments = [];

for (const item of $input.all()) {
  const payout_id = item.json.payout_id;
  if (!payout_id) continue;

  let page = 1;
  const per = 10;

  while (true) {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.gobiz.co.id/v1/merchants/payouts/${payout_id}/details?page=${page}&per=${per}`,
      headers: {
        accept: 'application/json, text/plain, */*',
        'accept-language': 'en-US,en;q=0.9,id;q=0.8',
        'authentication-type': 'go-id',
        authorization,
        'content-type': 'application/json',
        origin: 'https://portal.gofoodmerchant.co.id',
        referer: 'https://portal.gofoodmerchant.co.id/',
        'user-agent': user_agent,
      },
      json: true,
      ignoreHttpStatusErrors: true,
    });

    const shares = (response && response.transaction_shares) || [];
    const adjustments = shares.filter(s => s.payment_type === 'wallet_transaction');
    allAdjustments = allAdjustments.concat(adjustments.map(a => ({ ...a, payout_id })));

    if (!response || !response.next_page) break;
    page = response.next_page;
  }
}

return allAdjustments.map(a => ({ json: a }));

